      email: user.email,
      browsingHistory: [...], // e.g. an array of URLs
      searchQueries: [...], // e.g. an array of search queries
      // Add more data harvesting logic here
    };

    // Update the user's data in the database
    await User.findByIdAndUpdate(user._id, { $set: { data: userData } });
